// 1. Carrega contrato de calibração do candidato Mauricio Alves dos Santos
return [
  {
    json: {
      profile_owner: "Mauricio Alves dos Santos",
      target_seniority: "Senior / Lead Architect",
      cargos_alvo: [
        "SRE Manager / Specialist",
        "Automation Architect",
        "Workload Automation Specialist",
        "Infrastructure Engineer - AI & Cloud",
        "Analista de Produção e Operações de TI SR",
        "Scheduler SR"
      ],
      core_keywords: [
        "control-m", "control m", "uc4", "automic", "maestro", 
        "tsm", "tivoli", "netbackup", "mainframe", "es9000", 
        "vsesa", "vm/vse", "tape library", "acsls", "unix", 
        "aix", "solaris", "hp-ux", "linux", "sap r/3", "sap",
        "batch", "workload", "scheduller", "scheduler"
      ],
      modern_keywords: [
        "python", "crewai", "n8n", "aws", "azure", "kubernetes", 
        "sre", "power bi", "machine learning", "ia generativa"
      ],
      major_accounts: ["TECBAN", "ENEL", "BUNGE", "UNILEVER", "FABER-CASTELL", "OESP"],
      thresholds: {
        high_match: 70,
        correction_min: 50,
        discard_threshold: 50
      },
      config: {
        telegram_chat_id: "SEU_TELEGRAM_CHAT_ID",
        audit_spreadsheet_id: "ID_PLANILHA_GOOGLE_SHEETS"
      }
    }
  }
];

// 3. Gate Antifraude & Confiabilidade (Filosofia Fail-Closed)
const items = $input.all();
const output = [];

const freeEmailDomains = [
  'gmail.com', 'hotmail.com', 'yahoo.com', 'outlook.com', 
  'bol.com.br', 'uol.com.br', 'live.com', 'icloud.com'
];

const fraudPatterns = [
  /taxa\s+(de\s+)?(inscri[cç][aã]o|processo|sele[cç][aã]o|cadastro)/i,
  /pagar\s+(pelo\s+)?(curso|treinamento|exame)/i,
  /chave\s+pix|dep[oó]sito\s+banc[aá]rio/i,
  /envie\s+(foto\s+do\s+)?(documento|rg|cpf|cnh|cart[aã]o)/i,
  /renda\s+extra\s+di[aá]ria|ganhe\s+dinheiro\s+f[aá]cil/i
];

for (const entry of items) {
  const item = entry.json;
  let isFraud = false;
  let reason = '';

  const email = (item.contact_email || '').toLowerCase();
  const domain = email.split('@')[1];
  if (domain && freeEmailDomains.includes(domain)) {
    if (item.company_size !== 'Startup/Individual') {
      isFraud = true;
      reason = `Domínio de e-mail gratuito (${domain}) em vaga corporativa`;
    }
  }

  const text = `${item.title || ''} ${item.description || ''} ${item.requirements || ''}`.toLowerCase();
  for (const pat of fraudPatterns) {
    if (pat.test(text)) {
      isFraud = true;
      reason = `Gatilho de fraude/golpe detectado no anúncio: ${pat.toString()}`;
      break;
    }
  }

  if (item.whois_age_days !== undefined && item.whois_age_days < 30) {
    isFraud = true;
    reason = `Domínio registrado há apenas ${item.whois_age_days} dias (< 30 dias)`;
  }

  output.push({
    json: {
      ...item,
      security_passed: !isFraud,
      fraud_reason: reason,
      validation_timestamp: new Date().toISOString()
    }
  });
}

return output;

// Log e Isolamento de Vaga Suspeita / Bloqueada
const items = $input.all();
return items.map(item => ({
  json: {
    evento: "AMEACA_BLOQUEADA_FAIL_CLOSED",
    vaga_bloqueada: item.json.title,
    empresa: item.json.company,
    motivo_descarte: item.json.fraud_reason,
    data_bloqueio: item.json.validation_timestamp,
    acao: "ISOLAMENTO_PREVENTIVO"
  }
}));

// 4. LLM Parser / Normalizador Estruturado em Schema Pydantic
const items = $input.all();
const output = [];

for (const entry of items) {
  const item = entry.json;
  const text = `${item.title} ${item.description} ${item.requirements}`.toLowerCase();

  const knownTech = [
    "control-m", "uc4", "maestro", "tsm", "netbackup", "sap r/3", 
    "mainframe", "aix", "linux", "unix", "python", "aws", "azure", 
    "kubernetes", "sre", "storage", "disaster recovery"
  ];
  const detectedStack = knownTech.filter(tech => text.includes(tech));

  let seniority = "Pleno";
  if (text.includes("sênior") || text.includes("senior") || text.includes("sr") || text.includes("lead") || text.includes("especialista")) {
    seniority = "Sênior / Especialista";
  } else if (text.includes("estagiário") || text.includes("estágio") || text.includes("júnior") || text.includes("jr")) {
    seniority = "Iniciante / N1";
  }

  output.push({
    json: {
      ...item,
      cargo_normalizado: item.title,
      senioridade_requerida: seniority,
      stack_tecnica: detectedStack,
      modalidade: text.includes("remoto") ? "Remoto" : (text.includes("híbrido") ? "Híbrido" : "Presencial"),
      sla_missao_critica: item.sla_requirement === "critical"
    }
  });
}

return output;

// 5. Motor de Match Semântico e Metrologia de Aderência
const profile = $('Loader: profile.json & Config').first().json;
const items = $input.all();
const output = [];

for (const entry of items) {
  const item = entry.json;
  const fullText = `${item.title} ${(item.stack_tecnica || []).join(' ')} ${item.requirements} ${item.description}`.toLowerCase();

  // 1. Core Match (Hard Skills de Missão Crítica)
  let coreMatches = 0;
  for (const kw of profile.core_keywords) {
    if (fullText.includes(kw.toLowerCase())) {
      coreMatches++;
    }
  }
  const coreScore = Math.min(60, coreMatches * 15);

  // 2. Modern Skills Match (Python, Nuvem, Kubernetes, IA)
  let modernMatches = 0;
  for (const kw of profile.modern_keywords) {
    if (fullText.includes(kw.toLowerCase())) {
      modernMatches++;
    }
  }
  const modernScore = Math.min(25, modernMatches * 10);

  // 3. Senioridade e Missão Crítica
  const isSenior = (item.senioridade_requerida || '').includes("Sênior") || (item.senioridade_requerida || '').includes("Especialista");
  const seniorityBonus = isSenior ? 15 : ((item.senioridade_requerida || '').includes("Iniciante") ? -50 : 0);
  const missionCriticalBonus = item.sla_missao_critica ? 10 : 0;

  let calculatedScore = Math.round(coreScore + modernScore + seniorityBonus + missionCriticalBonus);
  calculatedScore = Math.max(10, Math.min(98, calculatedScore));

  let status = 'BAIXA';
  if (calculatedScore >= profile.thresholds.high_match) {
    status = 'ALTA_PRIORIDADE';
  } else if (calculatedScore >= profile.thresholds.correction_min) {
    status = 'LOOP_CORRECAO';
  }

  output.push({
    json: {
      ...item,
      match_score: calculatedScore,
      status: status,
      candidato: profile.profile_owner,
      justificativa: `Score de ${calculatedScore}% via similaridade metrológica (${coreMatches} core skills, ${modernMatches} modern skills, senioridade: ${item.senioridade_requerida})`
    }
  });
}

return output;

// 6. Agente ATS: Personalização STAR sem invenção de dados
const items = $input.all();
const output = [];

for (const entry of items) {
  const item = entry.json;

  const starHighlights = [
    "SITUAÇÃO/TAREFA: Gestão de orquestração de processamento batch e fechamento financeiro para contas críticas (TECBAN, ENEL, FABER-CASTELL, BUNGE) na TIVIT. AÇÃO: Configuração e monitoração avançada via Control-M e UC4-Global com resolução proativa de abends e reprocessamento. RESULTADO: Cumprimento estrito de 100% dos SLAs em janelas de fechamento de alta criticidade.",
    "SITUAÇÃO/TAREFA: Administração de ambientes massivos de Backup e Recuperação de Desastres na IBM e TIVIT. AÇÃO: Gerenciamento de políticas de retenção em Tivoli Storage Manager (TSM) e Veritas NetBackup operando Tape Libraries heterogêneas (ACSLS). RESULTADO: Garantia total de restauração de bases de dados essenciais e continuidade de negócios.",
    "SITUAÇÃO/TAREFA: Integração entre infraestrutura legada e demandas contemporâneas de automação. AÇÃO: Aplicação prática de Python, CrewAI, N8N, aliada a certificações AWS Cloud Practitioner, Azure AZ-900 e AI-900. RESULTADO: Redução drástica de intervenções manuais mantendo rastreabilidade total e governança."
  ];

  const coverLetter = `Prezada equipe de Atração de Talentos da ${item.company},

Apresento meu interesse na oportunidade de ${item.title}. Com mais de 25 anos dedicados à confiabilidade operacional em ambientes de missão crítica (TIVIT, IBM, Unilever, Saint Gobain, Comgás), atuo com foco rigoroso em tolerância zero a falhas e cumprimento de SLAs.

Possuo sólida vivência em orquestração de fluxos complexos (${(item.stack_tecnica || []).join(', ') || 'Control-M, TSM e sistemas corporativos'}) e conecto essa experiência à automação inteligente com Python, Nuvem (AWS/Azure) e IA.

Coloco-me à disposição para detalhar como minha solidez operacional pode agregar valor imediato e segurança aos sistemas da ${item.company}.

Atenciosamente,
Mauricio Alves dos Santos`;

  output.push({
    json: {
      ...item,
      carta_apresentacao_ats: coverLetter,
      destaques_star: starHighlights,
      anexo_curriculo: "curriculo_ats_mauricio_santos.pdf",
      pronto_para_notificacao: true
    }
  });
}

return output;

// 7. Simulação e Notificação Human-in-the-Loop
const items = $input.all();
return items.map(item => ({
  json: {
    status_aprovacao: "NOTIFICACAO_GERADA",
    empresa: item.json.company,
    cargo: item.json.title,
    score_match: `${item.json.match_score}%`,
    acao_requerida: "Candidato decide no Telegram: [Aprovar Envio] ou [Rejeitar Vaga]",
    preview_telegram: `🎯 NOVA VAGA ASSERTIVA (${item.json.match_score}%)
Empresa: ${item.json.company}
Cargo: ${item.json.title}
Status: Pronto para Envio`,
    candidatura_aprovada_auto_test: true,
    ...item.json
  }
}));

// 8. Dispatcher: Candidatura Oficial (Gmail / E-mail)
const items = $input.all();
return items.map(item => ({
  json: {
    status_envio: "PRONTO_PARA_TRANSMISSAO",
    destinatario: item.json.contact_email,
    assunto: `Candidatura: ${item.json.title} - Mauricio Alves dos Santos`,
    anexo: item.json.anexo_curriculo,
    corpo_resumo: (item.json.carta_apresentacao_ats || '').substring(0, 150) + "...",
    timestamp_envio: new Date().toISOString()
  }
}));

// 9. Painel Final de Auditoria, Rastreabilidade e Telemetria
const items = $input.all();
const totalAprovadas = items.length;

return [
  {
    json: {
      relatorio_execucao: {
        timestamp: new Date().toISOString(),
        vagas_com_alta_aderencia: totalAprovadas,
        candidato: "Mauricio Alves dos Santos",
        detalhes: items.map(i => ({
          cargo: i.json.assunto || i.json.title,
          destino: i.json.destinatario || i.json.contact_email,
          status: i.json.status_envio || "PRONTO_PARA_TRANSMISSAO"
        })),
        status_geral: "SUCESSO_PIPELINE_EXECUTADO_COM_MAXIMA_ASSERTIVIDADE"
      }
    }
  }
];
